        :param (str) text: text to be annotated
        :param (list[str]) annotators: a list of annotator names

        See a list of valid annotator names here:
          http://stanfordnlp.github.io/CoreNLP/annotators.html

        :return (AnnotatedDocument): an annotated document
        """
        if annotators is None:
            annotators = self.annotators
        if self.server is None:
            raise RuntimeError('CoreNLP server is not running.')
        if not text.strip():
            return AnnotatedDocument(text, annotators)
        payload = {'properties': self.properties, 'outputFormat': 'json'}
        if annotators:
            payload['annotators'] = ','.join(annotators)
        if self.timeout:
            payload['timeout'] = self.timeout
        payload['sentenceDelimiter'] = self.sentence_delimiter
        payload['input'] = text
        response = self.server.annotate(payload)
        return AnnotatedDocument(text, annotators, response)

