def moving_average(data, periods, type='simple'):
    """
    compute a <periods> period moving average.
    type is 'simple' | 'exponential'
    """
    if type == 'simple':
        return [data[i:i+periods].mean() for i in range(len(data) - periods + 1)]
    elif type == 'exponential':
        alpha = 2.0 / (periods + 1.0)
        return [alpha * data[i] + (1.0 - alpha) * data[i-1] if i > 0 else data[i] for i in range(len(data))]

